36	void IPC::serverAccept(Daemon &daemon) {
37	  int client = accept(m_serverFd, nullptr, nullptr);
38	  char buffer[1024];
39	  ssize_t bytes = ::read(client, buffer, sizeof(buffer));
40	  char bad_video_message[] =
41	      "Problem with video file, please delete ~/.cache/yin and try again";
42	  char no_hardware_decoding[] =
43	      "Hardware decoding is unavailable, cannot proceed"; // maybe we can,
44	                                                          // we'll find out
45	  char no_history[] = "No wallpaper previously set on this monitor";
46	  char success_message[] = "Img sent to daemon!";
47	  if (bytes > 0) {
48	    auto message = DeserializeMessage(buffer, bytes);
49	    if (std::holds_alternative<MonitorSizeMessage>(message)) {
50	      auto mes = std::get<MonitorSizeMessage>(message);
51	
52	      if (auto *monitor = daemonFindMonitor(daemon, mes.monitor)) {
53	        std::string dimensions = std::to_string(monitor->m_bufferWidth) + "x" +
54	                                 std::to_string(monitor->m_bufferHeight);
55	
56	        write(client, dimensions.data(), dimensions.size());
57	      }
58	    } else if (std::holds_alternative<SetWallpaperMessage>(message)) {
59	      auto mes = std::get<SetWallpaperMessage>(message);
60	
61	      WallpaperBindError error = Success;
62	      if (!mes.monitor.has_value()) {
63	        // No --output: apply to every monitor so all decodes and commits happen
64	        // in this single IPC call, letting the compositor batch both frames.
65	        for (auto &m : daemon.m_monitors) {
66	          error = m->setWallpaper(mes.imgPath, mes.transition);
67	          if (error != Success) break;
68	        }
69	      } else {
70	        auto monitor = daemonFindMonitor(daemon, mes.monitor);
71	        if (monitor) error = monitor->setWallpaper(mes.imgPath, mes.transition);
72	      }
73	
74	      if (error == BadVideo) {
75	        write(client, bad_video_message, std::strlen(bad_video_message));
76	      }
77	      if (error == NoHarwareDecoding) {
78	        write(client, no_hardware_decoding, std::strlen(no_hardware_decoding));
79	      }
80	      if (error == Success) {
81	        write(client, success_message, std::strlen(success_message));
82	      }
83	    } else if (std::holds_alternative<PlayPauseMessage>(message)) {
84	      auto mes = std::get<PlayPauseMessage>(message);
85	      auto monitor = daemonFindMonitor(daemon, mes.monitor);
86	      monitor->setPlayPause(mes.play);
87	    } else if (std::holds_alternative<RestoreMessage>(message)) {
88	      auto mes = std::get<RestoreMessage>(message);
89	      auto monitor = daemonFindMonitor(daemon, mes.monitor);
90	      auto error = monitor->restoreWallpaper();
91	      if (error == BadVideo) {
92	        write(client, bad_video_message, std::strlen(bad_video_message));
93	      }
94	      if (error == NoHarwareDecoding) {
95	        write(client, no_hardware_decoding, std::strlen(no_hardware_decoding));
96	      }
97	      if (error == Success) {
98	        write(client, success_message, std::strlen(success_message));
99	      }
100	      if (error == NoHistory) {
101	        write(client, no_history, std::strlen(no_history));
102	      }
103	    }
104	  }
105	  close(client);
106	}
